const here = position();
if (inventory_count('cobblestone') < 3) {
  const opened = await open_chest();
  if (!opened.ok) {
    return { done: false, detail: opened.detail };
  }
  const took = await withdraw('cobblestone', 3);
  if (!took.ok) {
    return { done: false, detail: took.detail };
  }
}
for (let i = 1; i <= 3; i++) {
  await place('cobblestone', here.x, here.y + i, here.z);
}
return { done: true, detail: 'raised a three block pillar' };
